CREATE TABLE `ai_analyses` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `prompt_kode` varchar(12) NOT NULL COMMENT 'Kode prompt: P1..P13, atau berantai mis. P5-P3, P10-P6',
  `indikator_id` tinyint(3) unsigned DEFAULT NULL,
  `opd_id` tinyint(3) unsigned DEFAULT NULL,
  `tahun` varchar(4) DEFAULT NULL,
  `hasil` longtext NOT NULL COMMENT 'Teks hasil analisis AI',
