  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ai_analyses_created_by_foreign` (`created_by`),
  KEY `ai_analyses_prompt_kode_index` (`prompt_kode`),
  KEY `ai_analyses_indikator_id_index` (`indikator_id`),
  KEY `ai_analyses_opd_id_index` (`opd_id`),
  CONSTRAINT `ai_analyses_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
