INSERT INTO `indikators` VALUES (86,'P-01',1,31,96,'Total Fertility Rate (TFR)','','Maintain / Stable','PK24 Kemendukbangga/\nBKKBN',1.84,'Indikator Program RPJMD (Program Pengendalian Penduduk)','Ketersediaan alokon untuk akseptor masih perlu dimaksimalkan, Masalah biaya hidup yang tinggi, tingginya partisipasi peremuan di dunia kerja, perubahan gaya hidup generasi muda serta disparitas demografi wilayah',NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(87,'P-02',2,31,96,'Age-Specific Fertility Rate (ASFR) 15-19 tahun','','Lower Better','PK24 Kemendukbangga',39.30,'Indikator Program RPJMD (Program Pengendalian Penduduk)',NULL,NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(88,'P-03',3,31,96,'Proporsi Kebutuhan KB yang Terpenuhi (Demand Satisfied)','','Higher Better','PK24 Kemendukbangga/\nBKKBN',7.10,'Indikator Kinerja Kunci (IKK) RPJMD Pengendalian Penduduk dan KB',NULL,NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(89,'P-04',4,32,98,'Rata-Rata Lama Sekolah Penduduk Usia 15 Tahun ke Atas (tahun)','','Higher Better','Susenas BPS',10.91,'Indikator Utama Pembangunan (IUP) RPJPD, Indikator Kinerja Daerah (IKD) RPJMD Aspek Kesejahteraan Masyarakat','1. Anak usia 15 tahun yang ATS (Anak Tidak Sekolah) dikarenakan sudah bekerja dan tidak ingin melanjutkan sekolah                     2. Melanjutkan ke sekolah pondok sehingga tidak tercatat di dapodik Kemendikdasmen                              3. Anak - anak berkebutuhan khusus yang tidak melanjutkan sekolah sehingga tidak tercatat di dapodik Kemendikdasmen','Menggalakkan kembali PKBM (Pusat Kegiatan Belajar Masyarakat) dengan kegiatannya kejar Paket A, B dan C','2026-07-30 08:21:04','2026-09-02 05:21:46'),(90,'P-05',5,32,98,'Angka Partisipasi Kasar (APK) Perguruan Tinggi (%)','','Higher Better','BPS Kota Sidoarjo \n*APK 19-24 th',18.34,'Indikator Kinerja Daerah (IKD) RPJMD Aspek Daya Saing Daerah (Indikator Proporsi Penduduk Berusia 15 Tahun ke Atas yang Berkualifikasi Pendidikan Tinggi)',NULL,NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(91,'P-06',6,32,105,'Jumlah Tenaga Kerja Tersertifikasi Kompetensi Kerja/ Persentase Pekerja Lulusan Pendidikan Menengah dan Tinggi yang Bekerja di Bidang Keahlian Menengah Tinggi','','Higher Better','Dinkopum',NULL,'Indikator Kinerja Kunci (IKK) RPJMD Ketenagakerjaan (Indikator % Pelatihan Berbasis Kompetensi)',NULL,NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(92,'P-07',7,32,97,'Prevalensi Stunting (Persentase Balita dengan Tinggi Badan di Bawah Standar)','','Lower Better','SKI/SSGI Kemenkes',10.60,'IUP RPJPD, Indikator Kinerja Daerah (IKD) RPJMD Aspek Kesejahteraan Masyarakat','Data stunting yang diakui adalah data penghitungan dari pusat, yaitu SKI (5 tahun sekali) dan SSGI (1 tahun sekali). Untuk tahun 2025 tidak ada pengukuran SSGI, sehingga angka capaian yang dipakai adalah SSGI pengukuran tahun 2024 yaitu 10,6%.\n10,6 ini tidak diukur berdasarkan TB/ U (umumnya penghitungan stunting), namun menggunakan sistem SAE (Small Area Estimation), yaitu metode untuk memperoleh nilai estimasi parameter yang reliabel pada level sub populasi (area atau domain) dimana ukuran sampelnya tidak cukup atau bahkan tidak ada sampelnya sama sekali. Sehingga angka 10,6 tersebut termasuk dalam salah satu yang RSE (Relative Standar Eror) nya tinggi (> 25%).',NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(93,'P-08',8,32,97,'Angka Kematian Bayi (AKB)','','Lower Better','Dinas Kesehatan',NULL,'Indikator Kegiatan Renstra Dinas Kesehatan','Jumlah kematian bayi 2025 adalah 193 orang. Jika disandingkan dengan target nasional (12,62 per 1.000 KH), maka capaian AKB tahun 2025 Kabupaten Sidoarjo masih dibawah target nasional. (Sumber data: MPDN, 2025. Diakses tgl: 14 Januari 2026)\nc) Indikator ini sebenarnya sudah tidak lagi dipasang di renstra baru, tahun 2025-2029. Karena renstra baru menyebutkan Angka Kematian Balita (berdasarkan indikator mandatory RIBK)',NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(94,'P-09',9,32,97,'Angka Kematian Ibu (AKI)','','Lower Better','Dinas Kesehatan',NULL,'IUP RPJPD, Indikator Kinerja Daerah (IKD) RPJMD Aspek Kesejahteraan Masyarakat','Jumlah kematian ibu tahun 2025 sebanyak 24 ibu, dan jumlah lahir hidup proyeksi menurut KMK tahun 2025 adalah 29.176',NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(95,'P-10',10,32,101,'Tingkat Kemiskinan','','Lower Better','Susenas BPS',4.53,'Indikator Sasaran RPJPD, Indikator Kinerja Utama (IKU) RPJMD',NULL,NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(96,'P-11',11,32,116,'Tingkat Partisipasi Angkatan Kerja Perempuan','','Higher Better','Sakernas BPS',54.23,'IUP RPJPD, Indikator Kinerja Daerah (IKD) RPJMD Aspek Kesejahteraan Masyarakat',NULL,NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(97,'P-12',12,32,116,'Persentase Pekerja Informal','','Lower Better','Sakernas BPS',NULL,'Indikator Kegiatan Renstra Dinkopum',NULL,NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(98,'P-13',13,32,116,'Persentase Penyandang Disabilitas Bekerja di Sektor Formal','','Higher Better','Dinas Sosial',NULL,'Indikator Kegiatan Renstra Dinkopum',NULL,NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(99,'P-14',14,32,101,'Gini Ratio','','Lower Better','Susenas BPS',0.33,'Indikator Sasaran RPJPD, Indikator Kinerja Utama (IKU) RPJMD',NULL,NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(100,'P-15',15,32,118,'Produk Domestik Regional Bruto (PDRB) Perkapita','','Higher Better','BPS',137.00,'Indikator Sasaran RPJPD, Indikator Kinerja Utama (IKU) RPJMD',NULL,NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(101,'P-16',16,32,116,'Tingkat Pengangguran Terbuka','','Lower Better','Sakernas BPS',6.49,'IUP RPJPD, Indikator Kinerja Utama (IKU) RPJMD',NULL,NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(102,'P-17',17,32,122,'Persentase Penambahan Wajib Pajak Hasil Ekstensifikasi','','Higher Better','BPPKAD',NULL,'ndikator Program RPJMD (Program Pengelolaan Pendapatan Daerah, indikator % Objek, subjek pajak baru yang terdata menjadi OP/WP); IUP RPJPD (Indikator Rasio pajak terhadap PDRB)',NULL,NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(103,'P-18',18,33,96,'Indeks Pembangunan Keluarga (i-bangga)','','Higher Better','Kemendukbangga/BKKBN',NULL,'IUP RPJPD, Indikator Kinerja Daerah (IKD) RPJMD Aspek Kesejahteraan Masyarakat',NULL,NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(104,'P-19',19,33,126,'Indeks Perlindungan Anak','','Higher Better','SIGA KemenPPPA',NULL,'IUP RPJPD, Indikator Kinerja Daerah (IKD) RPJMD Aspek Kesejahteraan Masyarakat',NULL,NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(105,'P-20',20,33,110,'Rumah Tangga dengan Akses Hunian Layak, Terjangkau, dan Berkelanjutan (%)','','Higher Better','DP2CKTR',NULL,'IUP RPJPD, Indikator Kinerja Daerah (IKD) RPJMD Aspek Kesejahteraan Masyarakat',NULL,NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(106,'P-21',21,33,113,'Rumah Tangga dengan Akses Sanitasi Aman (%)','','Higher Better','DPUPR',NULL,'IUP RPJPD, Indikator Kinerja Daerah (IKD) RPJMD Aspek Geografi dan Demografi',NULL,NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(107,'P-22',22,33,96,'Indeks Lansia Berdaya','','Higher Better','PK23 Kemendukbangga/ BKKBN',NULL,'Indikator Program RPJMD (Program Pemberdayaan dan Peningkatan Keluarga Sejahtera)',NULL,NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(108,'P-23',23,33,129,'Indeks Pengasuhan Keluarga yang Memiliki Remaja','','Higher Better','PK23 Kemendukbangga/ BKKBN',NULL,'Indikator Program RPJMD (Program Pemberdayaan dan Peningkatan Keluarga Sejahtera)',NULL,NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(109,'P-24',24,33,97,'Cakupan Kepesertaan Jaminan Kesehatan Nasional (%)','','Higher Better','BPJS Kesehatan',NULL,'Indikator Kinerja Daerah (IKD) RPJMD Aspek Kesejahteraan Masyarakat',NULL,NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(110,'P-25',25,34,96,'Persentase Kampung Keluarga Berkualitas Mandiri','','Higher Better','Kemendukbangga',NULL,'Indikator Kinerja Kunci (IKK) RPJMD Administrasi Kependudukan dan Pencatatan Sipil (Indikator',NULL,NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(111,'P-26',26,34,131,'Kepadatan Penduduk','','Proportional','BPS',NULL,'Substansi tekanan kependudukan melalui indikator Laju Pertumbuhan Penduduk (IKD RPJMD); Rasio Permukiman Layak Huni; Persentase Pengurangan Luasan Permukiman Kumuh di Kawasan Perkotaan; Persentase Penurunan Rumah Tidak Layak Huni; dan Persentase Perumahan yang Tertata (Indikator Program RPJMD)',NULL,NULL,'2026-07-30 08:21:04','2026-09-02 05:21:46'),(112,'P-27',27,35,132,'Cakupan (Persentase) Kepemilikan Akta Kelahiran Balita (0-4 tahun)','','Higher Better','Dispendukcapil',0.98,'Indikator Kinerja Kunci (IKK) RPJMD Administrasi Kependudukan dan Pencatatan Sipil (Indikator Persentase Kepemilikan Akta Kelahiran Usia 0-18), Indikator Sasaran Renstra/Indikator Kinerja Utama (IKU) Kepala Dispendukcapil','Kurangnya ketersediaan SDM untuk memproses akta kelahiran balita (0-4 tahun)','PKS kerjasama dengan mitra layanan (RS, Puskesmas, dsb) dan PKS kerjasama dengan Perguruan Tinggi untuk program magang','2026-07-30 08:21:04','2026-09-02 05:21:46'),(113,'P-28',28,35,132,'Cakupan (Persentase) Kepemilikan Akta Cerai bagi Penduduk yang Bercerai','','Higher Better','Dispendukcapil, Pengadilan Agama, Pengadilan Negeri',1.00,'Indikator Kinerja Kunci (IKK) RPJMD Administrasi Kependudukan dan Pencatatan Sipil (Indikator % Kepemilikan Akta Perceraian), Indikator Sasaran Renstra/IKU Kepala  Dispendukcapil','Kurangnya kesadaran masyarakat untuk melakukan update dokumen kependudukan (Kartu Keluarga) khususnya pada pembaruan akta cerai pada status cerai','Layanan terintegrasi akta perceraian, status cerai pada KK otomatis diperbarui, dan melaksanakan PKS dengan Pengadilan agama terkait penerbitan KK baru bagi penduduk yang diterbitkan surat cerainya oleh Pengadilan Agama','2026-07-30 08:21:04','2026-09-02 05:21:46'),(114,'P-29',29,35,132,'Cakupan (Persentase) Kepemilikan Akta Nikah','','Higher Better','Dispendukcapil',1.00,'Indikator Kinerja Kunci (IKK) RPJMD Administrasi Kependudukan dan Pencatatan Sipil (Indikator % Kepemilikan Akta Perkawinan), Indikator Sasaran Renstra/IKU Kepala Dispendukcapil','Kurangnya kesadaran masyarakat untuk melakukan update dokumen kependudukan (Kartu Keluarga) khususnya pada pembaruan akta perkawinan/surat nikah pada status kawin','Layanan terintegrasi akta perkawinan, status kawin pada KK otomatis diperbarui, dan melaksanakan PKS dengan Kemenag/KUA  terkait penerbitan KK baru bagi penduduk yang diterbitkan surat kawinnya oleh KUA','2026-07-30 08:21:04','2026-09-02 05:21:46'),(115,'P-30',30,35,132,'Cakupan (Persentase) Kepemilikan Akta Kematian bagi Penduduk yang Meninggal','','Higher Better','Dispendukcapil',1.00,'Indikator Sasaran Renstra/IKU Kepala Dispendukcapil (Indikator % Kepemilikan Akta Kematian)','Kurangnya kesadaran masyarakat untuk mengurus akta kematian bagi keluarganya yang mengalami peristiwa kematian, sehingga data kependudukannya belum mutakhir','Layanan e tamat yang bekerjasama dengan mitra rumah sakit dalam kepengurusan akta kematian','2026-07-30 08:21:04','2026-09-02 05:21:46');
