INSERT INTO `renaksi_programs` VALUES (1,1,'DPMPTSP','2025',118,'2.18.04','Program Pelayanan Penanaman Modal','Jemput Bola',NULL,NULL,'kuantitatif',550.00,'Nib',452.00,NULL,NULL,NULL,NULL,'**Analisis:**\nCapaian realisasi penerbitan NIB sebesar 452 dari target 550 (82,18%) menunjukkan bahwa program jemput bola belum berjalan optimal dalam menjangkau pelaku usaha di Kabupaten Sidoarjo. Ketidaktercapaian target ini berisiko menghambat formalisasi sektor informal, yang secara langsung berdampak pada stagnasi data PDRB perkapita serta sulitnya memetakan intervensi untuk menekan angka kemiskinan dan ketimpangan ekonomi (Gini Ratio).\n\n**Rekomendasi:**\n*   **Evaluasi Geospasial:** Melakukan pemetaan ulang wilayah dengan konsentrasi pelaku usaha mikro terbanyak yang belum terdaftar, lalu mengalihkan fokus lokasi jemput bola ke titik-titik tersebut.\n*   **Optimalisasi Kolaborasi Kewilayahan:** Melibatkan perangkat desa/kelurahan dan pendamping UMKM setempat untuk melakukan pendataan *door-to-door* guna memastikan target sasaran tepat sasaran dan memiliki kesiapan dokumen.\n*   **Penyederhanaan Alur Pendampingan:** Menyediakan layanan asistensi teknis di lokasi jemput bola agar pelaku usaha tidak hanya terdata, tetapi langsung mendapatkan NIB di tempat (on-the-spot).\n*   **Integrasi Data Sektoral:** Melakukan sinkronisasi data dengan Dinas Koperasi dan UKM untuk menyasar pelaku usaha yang sedang mengajukan bantuan atau pelatihan, sehingga proses formalisasi NIB menjadi syarat wajib yang terfasilitasi.\n*   **Monitoring Berkala:** Menetapkan target bulanan yang lebih ketat dengan mekanisme *review* mingguan untuk mengidentifikasi hambatan teknis di lapangan secara cepat sebelum akhir tahun anggaran.',100,95,99,97,'Tidak Tercapai','2026-08-17 17:30:30','2026-09-02 06:06:02'),(2,2,'DPMPTSP','2025',118,'2.18.06','Program Pengelolaan Data dan Sistem Informasi','Pengawasan','12.12 Triliun','18.88 Triliun','kualitatif',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,100,95,99,97,'Tercapai','2026-08-17 17:30:30','2026-09-05 22:10:17'),(3,3,'Disnaker','2025',116,'2.07.03','Program Pelatihan Kerja Dan Produktivitas Tenaga Kerja','Pelaksanaan Pelatihan berdasarkan Unit Kompetensi',NULL,NULL,'kuantitatif',21.00,'Kegiatan',21.00,'- Karena ini masuk POKIR DPRD, OPD tidak bisa mengontrol, dan fakta dilapangan peserta merupakan konstituen anggota dewan\n- Tidak menyasar usia pekerja produktif',NULL,NULL,NULL,NULL,97,101,98,NULL,'Tercapai','2026-08-17 17:30:30','2026-09-02 06:06:02'),(4,4,'DP3AKB (PPPA)','2025',96,'2.08.02','PUG dan Pemberdayaan Perempuan','Pelatihan Membatik (Ecoprint) Bagi Perempuan',NULL,NULL,'kuantitatif',250.00,'Peserta',250.00,'- Ketidaksanggupan peserta mengikuti sampai akhir pelatihan, dan digantikan dengan peserta yang mau melanjutkan',NULL,NULL,NULL,NULL,96,97,95,100,'Tercapai','2026-08-17 17:30:30','2026-09-02 06:06:02'),(5,5,'DP3AKB (PPPA)','2025',96,'2.08.02','PUG dan Pemberdayaan Perempuan','Sosialisasi 2P (Pelopor dan Pelapor) di SMP untuk mencegah Bullying',NULL,NULL,'kuantitatif',6.00,'Sekolah',6.00,'- Hanya bisa mencakup 6 sekolah saja, karena keterbatasan anggaran',NULL,NULL,NULL,NULL,104,108,103,87,'Tercapai','2026-08-17 17:30:30','2026-09-02 06:06:02'),(6,6,'DP3AKB (PPPA)','2025',96,'2.08.02','PUG dan Pemberdayaan Perempuan','Musrembang Anak, SAJO (Suara Anak Sidoarjo)',NULL,NULL,'kuantitatif',100.00,'Orang',100.00,'- Beberapa peserta ada yang tidak mengikuti kegiatan karena tidak mendapat ijin dari sekolah, undangan terlambat datang','1x setahun',NULL,NULL,NULL,104,NULL,NULL,NULL,'Tercapai','2026-08-17 17:30:30','2026-09-02 06:06:02'),(7,7,'DP3AKB (PPPA)','2025',96,'2.08.02','PUG dan Pemberdayaan Perempuan','Musrenbang Perempuan',NULL,NULL,'kuantitatif',120.00,'Orang',120.00,NULL,'1x setahun',NULL,NULL,NULL,104,NULL,NULL,NULL,'Tercapai','2026-08-17 17:30:30','2026-09-02 06:06:02'),(8,8,'DP3AKB (PPPA)','2025',96,'2.08.02','PUG dan Pemberdayaan Perempuan','HAN 2025 (Hari Anak Nasional)',NULL,NULL,'kuantitatif',200.00,'O